#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef CHECK_CUDA
#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA tensor")
#endif
#ifndef CHECK_CONTIGUOUS
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
#endif
#ifndef CHECK_INPUT
#define CHECK_INPUT(x) CHECK_CUDA(x); CHECK_CONTIGUOUS(x)
#endif

// ---------------------------------------------------------------
// Kernel: per‑sample mean
// ---------------------------------------------------------------
template <int TPB>
__global__ void layernorm_mean_kernel(const __half* __restrict__ input,
                                      float* __restrict__ mean,
                                      int N) {
    const int batch = blockIdx.x;
    const int tid   = threadIdx.x;
    const __half* batch_ptr = input + (size_t)batch * N;

    float sum = 0.0f;
    for (int i = tid; i < N; i += TPB) {
        sum += __half2float(batch_ptr[i]);
    }

    __shared__ float sh[TPB];
    sh[tid] = sum;
    __syncthreads();

    for (int stride = TPB / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sh[tid] += sh[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        mean[batch] = sh[0] / static_cast<float>(N);
    }
}

// ---------------------------------------------------------------
// Kernel: per‑sample variance
// ---------------------------------------------------------------
template <int TPB>
__global__ void layernorm_var_kernel(const __half* __restrict__ input,
                                     const float* __restrict__ mean,
                                     float* __restrict__ var,
                                     int N) {
    const int batch = blockIdx.x;
    const int tid   = threadIdx.x;
    const __half* batch_ptr = input + (size_t)batch * N;
    const float mu = mean[batch];

    float s = 0.0f;
    for (int i = tid; i < N; i += TPB) {
        float x = __half2float(batch_ptr[i]);
        float d = x - mu;
        s += d * d;
    }

    __shared__ float sh[TPB];
    sh[tid] = s;
    __syncthreads();

    for (int stride = TPB / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sh[tid] += sh[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        var[batch] = sh[0] / static_cast<float>(N);
    }
}

// ---------------------------------------------------------------
// Kernel: forward (normalize + affine)
// ---------------------------------------------------------------
template <int TPB>
__global__ void layernorm_forward_kernel(const __half* __restrict__ input,
                                         const float* __restrict__ mean,
                                         const float* __restrict__ var,
                                         const __half* __restrict__ weight,
                                         const __half* __restrict__ bias,
                                         __half* __restrict__ output,
                                         int N,
                                         float eps) {
    const int batch = blockIdx.x;
    const int tid   = threadIdx.x;
    const __half* in_ptr  = input  + (size_t)batch * N;
    const __half* w_ptr   = weight + (size_t)batch * N;
    const __half* b_ptr   = bias   + (size_t)batch * N;
    __half* out_ptr        = output + (size_t)batch * N;

    const float mu = mean[batch];
    const float sigma = rsqrtf(var[batch] + eps);   // 1/sqrt(var+eps)

    for (int i = tid; i < N; i += TPB) {
        float x = __half2float(in_ptr[i]);
        float w = __half2float(w_ptr[i]);
        float b = __half2float(b_ptr[i]);
        float y = (x - mu) * sigma;   // normalize
        y = y * w + b;                // affine
        out_ptr[i] = __float2half(y);
    }
}

// ---------------------------------------------------------------
// C++ wrappers
// ---------------------------------------------------------------
torch::Tensor layernorm_mean_cuda(torch::Tensor input, int64_t normalized_size) {
    CHECK_INPUT(input);
    TORCH_CHECK(input.dim() >= 2, "input must have at least 2 dimensions");
    const int64_t B = input.size(0);
    const int N = static_cast<int>(normalized_size);
    auto mean = torch::empty({B}, torch::dtype(torch::kFloat32).device(input.device()));

    constexpr int TPB = 256;
    dim3 block(TPB);
    dim3 grid(B);

    layernorm_mean_kernel<TPB><<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        mean.data_ptr<float>(),
        N);
    cudaDeviceSynchronize();

    return mean;
}

torch::Tensor layernorm_var_cuda(torch::Tensor input,
                                 torch::Tensor mean,
                                 int64_t normalized_size,
                                 float eps) {
    CHECK_INPUT(input);
    CHECK_INPUT(mean);
    const int64_t B = input.size(0);
    const int N = static_cast<int>(normalized_size);
    auto var = torch::empty({B}, torch::dtype(torch::kFloat32).device(input.device()));

    constexpr int TPB = 256;
    dim3 block(TPB);
    dim3 grid(B);

    layernorm_var_kernel<TPB><<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        N);
    cudaDeviceSynchronize();

    return var;
}

torch::Tensor layernorm_forward_cuda(torch::Tensor input,
                                    torch::Tensor mean,
                                    torch::Tensor var,
                                    torch::Tensor weight,
                                    torch::Tensor bias,
                                    float eps) {
    CHECK_INPUT(input);
    CHECK_INPUT(mean);
    CHECK_INPUT(var);
    CHECK_INPUT(weight);
    CHECK_INPUT(bias);

    const int64_t B = input.size(0);
    const int64_t N = input.numel() / B;   // flattened normalized dimensions
    auto output = torch::empty_like(input);

    constexpr int TPB = 256;
    dim3 block(TPB);
    dim3 grid(B);

    layernorm_forward_kernel<TPB><<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        reinterpret_cast<const __half*>(weight.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(bias.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        static_cast<int>(N),
        eps);
    cudaDeviceSynchronize();

    return output;
}

// ---------------------------------------------------------------
// PyBind bindings
// ---------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("layernorm_mean_cuda", &layernorm_mean_cuda, "LayerNorm mean (CUDA)");
    m.def("layernorm_var_cuda", &layernorm_var_cuda, "LayerNorm variance (CUDA)");
    m.def("layernorm_forward_cuda", &layernorm_forward_cuda, "LayerNorm forward (CUDA)");
}
