        var  = layernorm_ext.layernorm_var_cuda(x, mean, N, self.eps) # (B,) float32

        # expand weight / bias to (B, N) without extra copies
        w_exp = self.weight.view(1, -1).expand(B, -1).contiguous()
        b_exp = self.bias.view(1, -1).expand(B, -1).contiguous()

        # final normalized output
        out = layernorm_ext.layernorm_forward_cuda(
            x, mean, var, w_exp, b_exp, self.eps
        )
